 "content": "def transform(grid):
    """Extend shared columns of matching edge markers toward the separator."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    separators = [r for r, row in enumerate(grid) if row and all(v == 2 for v in row)]
    if not separators:
        return out
    sep = separators[0]
    if sep <= 0 or sep >= h - 1:
        return out
    top, bottom = grid[0], grid[-1]
    for c in range(w):
        if top[c] != 0 and top[c] == bottom[c]:
            for r in range(1, sep):
                if out[r][c] == 0:
                    out[r][c] = 4
    return out
